import json, os, glob

files = sorted(glob.glob(\"results/**/5method_leadlag.json\", recursive=True))
for fp in files:
    with open(fp) as f:
        m = json.load(f)

    pairs = m.get(\"pairs\", m.get(\"pair_results\", []))
    if isinstance(pairs, dict):
        items = list(pairs.values())
    elif isinstance(pairs, list):
        items = pairs
    else:
        items = []

    naive_sig = 0
    total = 0
    for pv in items:
        if not isinstance(pv, dict):
            continue
        fwd = pv.get(\"forward\", pv)
        if isinstance(fwd, dict):
            nx = fwd.get(\"naive_xcorr\", {})
            if isinstance(nx, dict):
                total += 1
                if nx.get(\"significant\", False):
                    naive_sig += 1

    d = os.path.dirname(os.path.dirname(fp))
    print(d, naive_sig, total, sep=\"|\")
